// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Wallet} from "../src/Wallet.sol";

uint256 constant VALUE_CAP = 1000000000000000000000000000000;

contract InvMutTest is Test {
    Wallet c;
    function setUp() public { c = new Wallet(); }

    function testFuzz_property(address actor, uint256 d, uint256 w) public {
        vm.assume(d <= VALUE_CAP);
        vm.assume(actor != address(0) && actor != address(c) && actor != address(this));
        uint256 cs;
        assembly { cs := extcodesize(actor) }
        vm.assume(cs == 0); // transfer must succeed on the reference
        d = bound(d, 1, 1000 ether);
        w = bound(w, 1, d);

        vm.deal(actor, d);
        vm.prank(actor);
        c.deposit{value: d}();

        vm.prank(actor);
        c.withdraw(w);

        // Rule: after crediting d and withdrawing w <= d, the remaining
        // credited balance is d - w < d, so withdrawing d again must revert.
        vm.prank(actor);
        bool ok;
        try c.withdraw(d) { ok = true; } catch { ok = false; }
        assertTrue(!ok);
    }
}
